import{z as p,x as d,o as r,c as A,q as s,j as o,D as t,d as a,s as l,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const v=JSON.parse('{"title":"KVM 与 QEMU 分工","description":"","frontmatter":{"title":"KVM 与 QEMU 分工","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kvm-qemu.md","filePath":"cs/kvm-qemu.md","lastUpdated":1791063341000}'),M={name:"cs/kvm-qemu.md"};function c(m,e,u,B,V,f){const E=d("Mermaid");return r(),A("div",null,[e[2]||(e[2]=s('<h1 id="kvm-与-qemu-分工" tabindex="-1">KVM 与 QEMU 分工 <a class="header-anchor" href="#kvm-与-qemu-分工" aria-label="Permalink to &quot;KVM 与 QEMU 分工&quot;">​</a></h1><div class="epigraph"><p>KVM 在内核提供 vCPU 与内存槽、处理 VM-exit；QEMU 在用户态模拟设备、启动固件、把 tap 接到 [网桥](/cs/bridge-tun-tap)。</p><footer>—— 据 Linux KVM 文档；QEMU 对 KVM 加速的说明；[ioctl](/cs/chardev-ioctl) 为 /dev/kvm 先修</footer></div><p><a href="/cs/hypervisor-types">类型</a> 把 Linux 放在中间。缺口是 <strong>分工</strong>：谁跑客户指令，谁模拟 virtio-blk。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>/dev/kvm</code> ioctl：建 VM、设内存、跑 vCPU。exit 原因：MMIO、PIO、halt。QEMU：注册内存区、模拟 PCI、调用 KVM_RUN。缺口：ioeventfd/irqfd 减退出；与 <a href="/cs/memcg">cgroup</a> 限制 QEMU 进程。本课不把每条 ioctl 列出。</p><p><span class="marginnote">Firecracker 后课用同一 KVM、更瘦设备模型。对象是加速器与模拟器切分。</span></p><p><span class="marginnote">术语翻译：VM-exit 就是「客户机一碰只有宿主才能处理的东西——设备寄存器、特殊指令、停机——CPU 硬件把控制权交还给 KVM」；每次往返要保存与恢复现场，代价数千个 CPU 周期，它是虚拟化性能账本上的第一行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>QEMU mmap 客户 RAM → KVM 设 slot → 循环 KVM_RUN → exit 则模拟设备再进。对照 <a href="/cs/fuse">FUSE</a>：用户完成内核发起的请求。对照 <a href="/cs/userfaultfd">uffd</a>：postcopy 迁移。对照 NVMe：virtio 是半虚拟，后课。</p>',9)),(r(),o(n,null,{default:t(()=>[l(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22QEMU%20%E7%94%A8%E6%88%B7%22%5D%20--%3E%20IOCTL%5B%22%2Fdev%2Fkvm%22%5D%0A%20%20IOCTL%20--%3E%20RUN%5B%22vCPU%20%E5%9C%A8%E5%AE%A2%E6%88%B7%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20RUN%20--%3E%20EX%5B%22VM-exit%22%5D%0A%20%20EX%20--%3E%20DEV%5B%22QEMU%20%E6%A8%A1%E6%8B%9F%E8%AE%BE%E5%A4%87%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("h2",{id:"机制",tabindex:"-1"},[a("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=i("p",null,[a("分工让内核保持小：不管 VGA 字体，只管进入客户与页表。用户态崩不等于宿主要 oops（通常）。不要写成 virt-manager 教程。与 [seccomp]：可锁 QEMU。与 "),i("a",{href:"/cs/kernel-audit"},"audit"),a("：ioctl 可记。")],-1)),(r(),o(n,null,{default:t(()=>[l(E,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20GUEST%5B%22guest%20%E5%86%99%E8%AE%BE%E5%A4%87%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20WAY%7B%22%E8%B5%B0%E5%93%AA%E6%9D%A1%E8%B7%AF%E5%BE%84%3F%22%7D%0A%20%20WAY%20--%3E%7C%22%E6%99%AE%E9%80%9A%20MMIO%20%2F%20PIO%22%7C%20EXIT%5B%22VM-exit%2C%20%E8%BF%9B%20QEMU%20%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20WAY%20--%3E%7C%22ioeventfd%22%7C%20SHORT%5B%22KVM%20%E7%9B%B4%E6%8E%A5%E9%80%9A%E7%9F%A5%E4%BA%8B%E4%BB%B6fd%2C%20%E4%B8%8D%E8%BF%9B%E7%94%A8%E6%88%B7%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20EXIT%20--%3E%20TAX%5B%22%E6%AF%8F%E6%AC%A1%E5%BE%80%E8%BF%94%E6%95%B0%E5%8D%83%E5%91%A8%E6%9C%9F%22%5D%0A%20%20SHORT%20--%3E%20FAST%5B%22virtio%20%E9%AB%98%E9%A2%91%20kick%20%E8%B5%B0%E8%BF%99%E9%87%8C%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=s('<p><span class="marginnote">数字实例：一次 VM-exit 加再进入约耗上千个 CPU 周期（微秒级）。guest 里一段纯计算代码几乎不 exit、能跑出接近原生的速度；而每次发包都写设备寄存器的老式网卡驱动，可能被这道税拖慢一个数量级——这正是 ioeventfd 与设备直通存在的理由。</span></p><p><span class="marginnote">直觉类比：KVM 是让客队上场打球的场地管理员，QEMU 是场外的器材室。客队每次要换器材（碰设备）就得吹哨暂停、由 QEMU 递东西；ioeventfd 相当于把最常用的器材直接搬到场边，免了这一次次吹哨。</span></p><p>性能：exit 率决定上限，后课直通。</p><p>实现上：ioeventfd 让设备 kick 不进 QEMU 用户循环。vCPU 线程是普通 Linux 任务，可被 cgroup 限。guest RAM 是 QEMU 的 mmap，KVM slot 指向它。 读法上只引用<a href="/cs/hypervisor-types">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>KVM 与 QEMU 分工</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 machine type。不保证 Windows Hyper-V 的对等分工。下一课硬件陷入：VMX VM-exit。</p><p>版本字段会变，课序钉的是机制对象「KVM 与 QEMU 分工」，不是某一主线内核的结构体名。 后课默认：KVM 跑 vCPU，QEMU 做设备。VMX 与退出原因，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KVM：vCPU/内存/exit；QEMU：设备与生命周期。</li><li>经 ioctl 与事件 fd 协作。</li><li>VMX/VM-exit 是下一课。</li><li>出处：KVM API；QEMU；Linux virt。</li></ul>',11))])}const U=p(M,[["render",c]]);export{v as __pageData,U as default};
